package com.jobcom.web;
import com.jobcom.dao.ResumeDAO;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.nio.file.*;import java.sql.SQLException;import java.util.*;
public class ResumeTemplateServlet extends HttpServlet{
 private final ResumeDAO dao=new ResumeDAO();
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{dao.ensure();q.setAttribute("templates",dao.templates(false));}catch(Exception e){getServletContext().log("Resume template list failed",e);q.setAttribute("error","Resume templates could not be loaded. Please check the database setup.");}String csrf=(String)q.getSession().getAttribute("csrf");if(csrf==null){csrf=UUID.randomUUID().toString();q.getSession().setAttribute("csrf",csrf);}q.setAttribute("csrf",csrf);q.getRequestDispatcher("/WEB-INF/views/admin/resume-templates.jsp").forward(q,p);}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{HttpSession s=q.getSession(false);if(s==null||!Objects.equals(s.getAttribute("csrf"),q.getParameter("csrf"))){p.sendError(403);return;}String action=q.getParameter("action");Path saved=null;try{if("toggle".equals(action)){dao.setTemplateActive(Long.parseLong(q.getParameter("id")),Boolean.parseBoolean(q.getParameter("active")));}else{String name=val(q,"name"),description=val(q,"description"),layout=val(q,"layout");if(name.isBlank()||name.length()>140)throw new IllegalArgumentException("Template name required (max 140 characters).");if(!Set.of("classic","compact","modern","creative","ocean","sunset","photo-violet","photo-emerald").contains(layout))layout="classic";Part file=q.getPart("template");String path=null;if(file!=null&&file.getSize()>0){if(file.getSize()>5L*1024*1024)throw new IllegalArgumentException("PDF must be under 5 MB.");byte[] sig=new byte[4];try(InputStream in=file.getInputStream()){if(in.read(sig)<4||sig[0]!='%'||sig[1]!='P'||sig[2]!='D'||sig[3]!='F')throw new IllegalArgumentException("Please upload a valid PDF ATS example/format.");}Path root=uploadRoot().resolve("resume-templates").normalize();Files.createDirectories(root);saved=root.resolve(UUID.randomUUID()+".pdf");try(InputStream in=file.getInputStream()){Files.copy(in,saved);}path="resume-templates/"+saved.getFileName();}dao.addTemplate(name,description,layout,path,((Number)s.getAttribute("adminId")).longValue());}p.sendRedirect(q.getContextPath()+"/admin/resume-templates?success=1");}catch(Exception e){if(saved!=null)Files.deleteIfExists(saved);getServletContext().log("Template save failed",e);q.setAttribute("error",e instanceof IllegalArgumentException?e.getMessage():"The template could not be saved. Please check the database setup and try again.");doGet(q,p);}}
 private String val(HttpServletRequest q,String k){String v=q.getParameter(k);return v==null?"":v.trim();}private Path uploadRoot(){String x=System.getenv("JOBCOM_UPLOAD_DIR");String real=getServletContext().getRealPath("/uploads");return Paths.get(x==null||x.isBlank()?(real==null?Paths.get(System.getProperty("user.home"),"Job.com","uploads").toString():real):x).toAbsolutePath().normalize();}
}
